let threaded = [];
try { threaded = $("🧵 نصّ السيرة من الجسم").all(); } catch (e) { threaded = []; }
const writes = $input.all();

let written = 0, failed = 0, chars = 0, elements = 0, truncated = 0;
const firstErrors = [];
const writtenPages = [];
for (let i = 0; i < writes.length; i++) {
  const j = writes[i].json || {};
  if (j.status === "written") {
    written++;
    chars += Number(j.textLength) || 0;
    elements += Number(j.chunkCount) || 0;
    if (j.truncated) truncated++;
    if (writtenPages.length < 25) writtenPages.push({ pageId: j.pageId, textLength: j.textLength, chunkCount: j.chunkCount, maxElementChars: j.maxElementChars });
  } else {
    failed++;
    if (firstErrors.length < 20) firstErrors.push({ pageId: j.pageId, error: j.error });
  }
}

let skipped = 0;
let maxElemSeen = 0;
const skipReasons = {};
for (let i = 0; i < threaded.length; i++) {
  const j = threaded[i].json || {};
  if (!j.ok) {
    skipped++;
    const k = j.reason || "غير محدد";
    skipReasons[k] = (skipReasons[k] || 0) + 1;
  }
  const m = Number(j.maxElementChars) || 0;
  if (m > maxElemSeen) maxElemSeen = m;
}

return [{ json: {
  total: threaded.length,
  written: written,
  skipped: skipped,
  failed: failed,
  failedPct: threaded.length ? Math.round((failed / threaded.length) * 1000) / 10 : 0,
  avgChars: written ? Math.round(chars / written) : 0,
  richTextElementsWritten: elements,
  truncatedRows: truncated,
  maxElementCharsSeen: maxElemSeen,
  skipReasons: skipReasons,
  firstErrors: firstErrors,
  writtenSample: writtenPages,
  finishedAt: new Date().toISOString()
} }];

const HEAD = "السيرة الذاتية ATS-friendly";
const WARN = "لم تُبنَ سيرة ATS";
const MAX = 1900;
const MAX_CHUNKS = 20;
const MIN_LEN = 80;
const OK_STATUS = "مكتمل";
const OK_SOURCE = "ترشيح";

function norm(s) { return String(s === null || s === undefined ? "" : s).toLowerCase().replace(/[^0-9a-f]/g, ""); }

function blockText(j) {
  if (typeof j.content === "string" && j.content.length > 0) return j.content;
  const t = String(j.type || "");
  const inner = t ? j[t] : null;
  if (!inner || typeof inner !== "object") return "";
  let rt = [];
  if (Array.isArray(inner.rich_text)) rt = inner.rich_text;
  else if (Array.isArray(inner.text)) rt = inner.text;
  else if (Array.isArray(inner.title)) rt = inner.title;
  let s = "";
  for (let k = 0; k < rt.length; k++) {
    const p = rt[k] || {};
    if (p.plain_text !== null && p.plain_text !== undefined) s += String(p.plain_text);
    else if (p.text && p.text.content !== null && p.text.content !== undefined) s += String(p.text.content);
  }
  return s;
}

const rows = $("📇 صفوف بلا نصّ ATS (مكتملة فقط)").all();

// تجميع البلوكات بمعرّف صفحتها المحمول في البيانات نفسها (root_id / parent.page_id).
// لا اعتماد على الترتيب ولا على pairedItem: الصفّ لا يأخذ إلا بلوكات صفحته هو،
// فاختلاط سيرة مرشّح بآخر مستحيل بنيوياً لا محتملاً.
const raw = $input.all();
let blockErr = "";
const groups = {};
let unattributed = 0;
let placeholders = 0;
for (let i = 0; i < raw.length; i++) {
  const j = (raw[i] && raw[i].json) || {};
  if (j.error) { blockErr = String((j.error && j.error.message) || j.error); continue; }
  if (!j.type && !j.id) { placeholders++; continue; }
  const owner = norm(j.root_id || (j.parent && (j.parent.page_id || j.parent.block_id)));
  if (!owner) { unattributed++; continue; }
  if (!groups[owner]) groups[owner] = [];
  groups[owner].push(j);
}

const out = [];
for (let r = 0; r < rows.length; r++) {
  const row = (rows[r] && rows[r].json) || {};
  const pageId = String(row.id || "");
  const key = norm(pageId);
  const props = row.properties || {};
  const fieldProp = props["ATS CV Text"] || {};
  const existing = Array.isArray(fieldProp.rich_text) ? fieldProp.rich_text : [];
  let existingText = "";
  for (let i = 0; i < existing.length; i++) existingText += String(existing[i].plain_text || "");
  const statusProp = props["حالة القراءة"] || {};
  const readStatus = String((statusProp.select && statusProp.select.name) || "");
  const sourceProp = props["Source"] || {};
  const sourceName = String((sourceProp.select && sourceProp.select.name) || "");

  const mine = (key && groups[key]) ? groups[key] : [];

  const kept = [];
  let droppedHead = 0;
  let emptyBlocks = 0;
  for (let i = 0; i < mine.length; i++) {
    const j = mine[i];
    const type = String(j.type || "");
    const t = blockText(j);
    const trimmed = t.trim();
    const isGenHead = (type.indexOf("heading") === 0 && trimmed.indexOf(HEAD) >= 0) || trimmed === HEAD;
    if (isGenHead) { droppedHead++; continue; }
    if (!trimmed) { emptyBlocks++; continue; }
    kept.push({ type: type, text: t });
  }

  let allParagraph = kept.length > 0;
  for (let i = 0; i < kept.length; i++) if (kept[i].type !== "paragraph") { allParagraph = false; break; }
  const joinMode = allParagraph ? "slices" : "lines";
  const JOIN = allParagraph ? "" : "\n";
  const parts = [];
  for (let i = 0; i < kept.length; i++) parts.push(kept[i].text);
  const text = parts.join(JOIN).trim();

  let ok = true;
  let reason = "";
  if (!pageId) { ok = false; reason = "لا معرّف صفحة"; }
  else if (existingText.trim().length > 0) { ok = false; reason = "الحقل غير فارغ (" + existingText.trim().length + " حرفاً) — لا يُدهس"; }
  else if (readStatus !== OK_STATUS) { ok = false; reason = "حالة القراءة ليست «" + OK_STATUS + "»: " + (readStatus || "فارغة"); }
  else if (sourceName !== OK_SOURCE) { ok = false; reason = "المصدر ليس «" + OK_SOURCE + "»: " + (sourceName || "فارغ"); }
  else if (mine.length === 0) { ok = false; reason = blockErr ? ("فشل قراءة بلوكات الصفحة: " + blockErr) : "لا بلوكات في الصفحة (قراءة فارغة)"; }
  else if (kept.length === 0) { ok = false; reason = "لا نصّ في بلوكات الصفحة"; }
  else if (text.indexOf("⚠️") === 0 || text.indexOf(WARN) >= 0) { ok = false; reason = "الجسم يحمل نصّ تحذير لا سيرة"; }
  else if (text.length < MIN_LEN) { ok = false; reason = "النصّ أقصر من " + MIN_LEN + " حرفاً (" + text.length + ")"; }

  const chunks = [];
  let truncated = false;
  if (ok) {
    for (let i = 0; i < text.length; i += MAX) {
      if (chunks.length >= MAX_CHUNKS) { truncated = true; break; }
      chunks.push({ text: { content: text.slice(i, i + MAX) } });
    }
  }
  let maxElem = 0;
  for (let i = 0; i < chunks.length; i++) { const n = chunks[i].text.content.length; if (n > maxElem) maxElem = n; }
  const body = { properties: { "ATS CV Text": { rich_text: chunks } } };

  out.push({ json: {
    pageId: pageId,
    ok: ok,
    reason: reason,
    readStatus: readStatus,
    source: sourceName,
    textLength: text.length,
    partsUsed: kept.length,
    joinMode: joinMode,
    droppedHeadBlocks: droppedHead,
    myBlocks: mine.length,
    rowsInBatch: rows.length,
    blockItems: raw.length,
    emptyOutputItems: placeholders,
    unattributedBlocks: unattributed,
    emptyBlocksSkipped: emptyBlocks,
    chunkCount: chunks.length,
    maxElementChars: maxElem,
    truncated: truncated,
    bodyJson: JSON.stringify(body)
  }, pairedItem: { item: r } });
}
return out;

function norm(s) { return String(s === null || s === undefined ? "" : s).toLowerCase().replace(/[^0-9a-f]/g, ""); }

// عناصر «🧵» التي مرّت بالشرط، بترتيبها — وهي نفسها التي دخلت عقدة الكتابة بالترتيب.
const src = [];
const all = $("🧵 نصّ السيرة من الجسم").all();
for (let i = 0; i < all.length; i++) { const j = all[i].json || {}; if (j.ok) src.push(j); }
const byId = {};
for (let i = 0; i < src.length; i++) byId[norm(src[i].pageId)] = src[i];

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  let err = "";
  if (r.error) err = (typeof r.error === "string") ? r.error : String(r.error.message || JSON.stringify(r.error));
  const failed = !!err || (!r.id && r.object !== "page");
  if (failed && !err) err = "استجابة غير متوقعة من نوشن";
  // المطابقة بمعرّف الصفحة الذي يعيده نوشن نفسه؛ وعند الفشل (لا id) نرجع للترتيب.
  const respKey = norm(r.id);
  const s = (respKey && byId[respKey]) ? byId[respKey] : (src[i] || {});
  out.push({ json: {
    pageId: s.pageId,
    status: failed ? "failed" : "written",
    reason: "",
    textLength: s.textLength,
    chunkCount: s.chunkCount,
    maxElementChars: s.maxElementChars,
    truncated: s.truncated,
    matchedBy: (respKey && byId[respKey]) ? "notionId" : "order",
    error: failed ? String(err).slice(0, 400) : ""
  }, pairedItem: { item: i } });
}
return out;

// عناصر الفرع السالب هي نفسها عناصر «🧵» بـ ok:false — كلّٓ يحمل سببه.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const s = items[i].json || {};
  out.push({ json: {
    pageId: s.pageId,
    status: "skipped",
    reason: s.reason,
    textLength: s.textLength,
    chunkCount: 0,
    maxElementChars: 0,
    truncated: false,
    error: ""
  }, pairedItem: { item: i } });
}
return out;
